INSERT INTO articles (id, title, slug, summary, body, published_at, active, category, author_name, reading_minutes, related_specialty_slug, content_language, content_kind, cover_image_url)
VALUES
 (gen_random_uuid(), 'Chế độ ăn DASH: giảm muối, lợi ích kiểm soát huyết áp và bảo vệ thành mạch',
  'che-do-an-dash-giam-muoi-loi-ich-kiem-soat-huyet-ap-va-bao-ve-thanh-mach',
  'Chế độ ăn DASH hạn chế natri, tăng kali, magie và chất xơ giúp hạ huyết áp và bảo vệ thành mạch.',
  'Chế độ ăn DASH (Dietary Approaches to Stop Hypertension) là phác đồ dinh dưỡng được khuyến cáo cho người tăng huyết áp: hạn chế natri dưới 5g muối mỗi ngày, tăng rau xanh, trái cây, ngũ cốc nguyên hạt và sản phẩm ít béo. Chất xơ, kali và magie từ rau củ giúp giãn mạch và giảm sức cản ngoại biên. Nên hạn chế thịt muối, đồ đóng hộp và nước dùng công nghiệp. Kết hợp vận động 150 phút mỗi tuần để đạt hiệu quả kiểm soát huyết áp tối ưu.',
  now() - interval '200 days', true, 'Tim mạch', 'Đội ngũ chuyên môn', 6, 'tim-mach', 'vi', 'GENERAL',
  '/media/articles/dinh-duong-tang-huyet-ap.jpg'),
 (gen_random_uuid(), 'Đái tháo đường thai kỳ: nghiệm pháp dung nạp 75g glucose và phác đồ điều hòa đường huyết',
  'dai-thao-duong-thai-ky-nghiem-phap-dung-nap-75g-glucose-va-phac-do-dieu-hoa-duong-huyet',
  'Sàng lọc đái tháo đường thai kỳ bằng nghiệm pháp dung nạp 75g glucose từ tuần 24-28 và quản lý bằng dinh dưỡng, insulin khi cần.',
  'Đái tháo đường thai kỳ (ĐTĐTK) là rối loạn dung nạp glucose xuất hiện lần đầu trong thai kỳ, được sàng lọc bằng nghiệm pháp dung nạp 75g đường uống ở tuần 24-28. Chẩn đoán dựa trên đường huyết lúc đói ≥ 5,1 mmol/L, sau tải glucose 1 giờ ≥ 10,0 mmol/L hoặc 2 giờ ≥ 8,5 mmol/L. Quản lý ban đầu bằng chế độ ăn phân bổ tinh bột hợp lý, vận động nhẹ; insulin được chỉ định khi đường huyết không đạt mục tiêu. Kiểm soát tốt giúp giảm nguy cơ thai to, sinh khó và hạ đường huyết trẻ sơ sinh.',
  now() - interval '190 days', true, 'Sản phụ khoa', 'Đội ngũ chuyên môn', 7, 'san-phu-khoa', 'vi', 'GENERAL',
  '/images/packages/womens-health.jpg'),
 (gen_random_uuid(), 'Dinh dưỡng thai kỳ theo từng tam cá nguyệt: bổ sung axit folic, sắt, canxi và DHA hợp lý',
  'dinh-duong-thai-ky-theo-tung-tam-ca-nguyet-bo-sung-axit-folic-sat-canxi-va-dha-hop-ly',
  'Nhu cầu dinh dưỡng thay đổi theo tam cá nguyệt: axit folic từ trước thụ thai, sắt tăng ở tam cá nguyệt 2-3, canxi và DHA cho phát triển xương và não bộ thai nhi.',
  'Dinh dưỡng thai kỳ cần được cá thể hóa theo từng giai đoạn. Tam cá nguyệt 1 ưu tiên axit folic 400 mcg/ngày từ trước thụ thai để phòng khuyết tật ống thần kinh. Tam cá nguyệt 2-3 tăng nhu cầu sắt (27-30 mg/ngày) phòng thiếu máu, canxi 1000 mg/ngày cho khoáng hóa xương thai nhi và DHA 200-300 mg/ngày hỗ trợ phát triển não bộ. Tránh cá nhiều thủy ngân, hạn chế caffeine dưới 200 mg/ngày và tuyệt đối không dùng rượu bia.',
  now() - interval '180 days', true, 'Sản phụ khoa', 'Đội ngũ chuyên môn', 6, 'san-phu-khoa', 'vi', 'GENERAL',
  '/images/packages/womens-health.jpg'),
 (gen_random_uuid(), 'Đột quỵ não cấp: nhận diện dấu hiệu FAST và quy tắc 4,5 giờ vàng tiêu sợi huyết',
  'dot-quy-nao-cap-nhan-dien-dau-hieu-fast-va-quy-tac-45-gio-vang-tieu-soi-huyet',
  'Nhận diện đột quỵ bằng thang điểm FAST và đưa đến viện trong cửa sổ điều trị 4,5 giờ để can thiệp tiêu sợi huyết kịp thời.',
  'Đột quỵ não cấp là tình trạng cấp cứu thần kinh với cửa sổ điều trị vàng 4,5 giờ từ thời điểm khởi phát. Thang điểm FAST giúp nhận diện nhanh: F (Face) mặt xệ một bên; A (Arm) tay yếu liệt; S (Speech) nói khó, líu lưỡi; T (Time) ghi nhớ thời điểm khởi phát và gọi cấp cứu 115 ngay. Điều trị tiêu sợi huyết tĩnh mạch chỉ thực hiện trong cửa sổ 4,5 giờ tại cơ sở có chụp cắt lớp đầy đủ. Phòng ngừa bao gồm kiểm soát huyết áp, chống rung nhĩ và bỏ thuốc lá.',
  now() - interval '170 days', true, 'Thần kinh', 'Đội ngũ chuyên môn', 6, 'than-kinh', 'vi', 'GENERAL',
  '/media/articles/than-kinh-dot-quy.jpg'),
 (gen_random_uuid(), 'Hội chứng khô mắt văn phòng: nguyên nhân chớp mắt ít trước máy tính và bổ sung nước mắt nhân tạo',
  'hoi-chung-kho-mat-van-phong-nguyen-nhan-chop-mat-it-truoc-may-tinh-va-bo-sung-nuoc-mat-nhan-tao',
  'Làm việc kéo dài trước màn hình giảm tần số chớp mắt gây khô mắt; quy tắc 20-20-20 và nước mắt nhân tạo không bảo quản là nền tảng điều trị.',
  'Hội chứng khô mắt văn phòng xảy ra khi tần số chớp mắt giảm từ 15-20 lần/phút còn 4-6 lần/phút lúc tập trung vào màn hình, khiến phim nước mắt bốc hơi quá mức. Điều kiện máy lạnh và ánh sáng xanh làm nặng thêm triệu chứng giác mạc cay xè, mờ nhìn thoáng qua. Nền tảng điều trị là quy tắc 20-20-20, chỉnh màn hình thấp hơn tầm mắt 15-20 độ và nước mắt nhân tạo không chất bảo quản dạng tép đơn liều. Khám chuyên khoa mắt khi có giảm thị lực kéo dài.',
  now() - interval '160 days', true, 'Mắt', 'Đội ngũ chuyên môn', 5, 'mat', 'vi', 'GENERAL',
  '/media/articles/cham-soc-suc-khoe-tong-quat.jpg'),
 (gen_random_uuid(), 'Mesotherapy vi điểm: cung cấp hạ vitamin và peptide nuôi dưỡng, làn da căng bóng mịn màng',
  'mesotherapy-vi-diem-cung-cap-ha-vitamin-va-peptide-nuoi-duong-lan-da-cang-bong-min-mang',
  'Mesotherapy vi điểm đưa dưỡng chất hạ vận vào trung bì giúp da căng bóng, mịn màng; cần thực hiện tại cơ sở y tế đủ điều kiện.',
  'Mesotherapy vi điểm là kỹ thuật tiêm vi nhũ tương vitamin, peptide và axit hyaluronic không liên kết vào trung bì da, kích thích tổng hợp collagen và cải thiện độ ẩm nền. Chỉ định phù hợp với da khô, da lão hóa nhẹ, sạm màu. Thủ thuật phải thực hiện tại cơ sở y tế có bác sĩ chuyên khoa da liễu, dụng cụ dùng một lần; chống chỉ định khi đang viêm da nhiễm trùng, thai kỳ hoặc dị ứng thành phần. Liệu trình thường 3-5 phiên cách nhau 2-4 tuần.',
  now() - interval '150 days', true, 'Da liễu', 'Đội ngũ chuyên môn', 5, 'da-lieu', 'vi', 'GENERAL',
  '/media/doctor-family-consult.jpg'),
 (gen_random_uuid(), 'Siêu âm thai 4D: hình thái học tuần 12, tuần 22, tuần 32 — tầm soát dị tật cấu trúc thai nhi',
  'sieu-am-thai-4d-hinh-thai-hoc-tuan-12-tuan-22-tuan-32-tam-soat-di-tat-cau-truc-thai-nhi',
  'Ba mốc siêu âm quan trọng trong thai kỳ: đo độ mờ da gáy tuần 11-13, tầm soát dị tật cấu trúc tuần 18-22 và đánh giá tăng trưởng tuần 30-32.',
  'Siêu âm thai là công cụ tầm soát dị tật cốt lõi với ba mốc chuẩn. Tuần 11-13 tuần 6 ngày: đo độ mờ da gáy và xương mũi, kết hợp Double test. Tuần 18-22: siêu âm hình thái học chi tiết đánh giá cấu trúc não, tim, thận, chi — mốc quan trọng nhất để phát hiện dị tật cấu trúc. Tuần 30-32: đánh giá tăng trưởng, lượng ối, vị trí nhau và dòng chảy Doppler. Kết hợp Triple test và NIPT theo chỉ định của bác sĩ sản khoa.',
  now() - interval '140 days', true, 'Sản phụ khoa', 'Đội ngũ chuyên môn', 6, 'san-phu-khoa', 'vi', 'GENERAL',
  '/images/packages/womens-health.jpg'),
 (gen_random_uuid(), 'Tầm soát phát hiện sớm tăng huyết áp và đái tháo đường tại y tế cơ sở — quản lý bệnh không lây nhiễm',
  'tam-soat-phat-hien-som-tang-huyet-ap-va-dai-thao-duong-tai-y-te-co-so-quan-ly-benh-khong-lay-nhiem',
  'Tầm soát huyết áp và đường huyết định kỳ tại y tế cơ sở giúp phát hiện sớm hai bệnh không lây nhiễm phổ biến nhất và phòng biến chứng tim mạch.',
  'Tăng huyết áp và đái tháo đường type 2 là hai bệnh không lây nhiễm âm thầm nhất, thường không triệu chứng cho đến khi xuất hiện biến chứng. Tầm soát tại y tế cơ sở: đo huyết áp mỗi lần khám sức khỏe, đường huyết đói mỗi 1-3 năm với người trên 35 tuổi hoặc có yếu tố nguy cơ. Phát hiện sớm cho phép can thiệp lối sống trước khi cần thuốc. Mục tiêu điều trị huyết áp < 130/80 mmHg và HbA1c < 7% giúp giảm đáng kể biến chứng tim mạch, thận và mắt.',
  now() - interval '130 days', true, 'Tim mạch', 'Đội ngũ chuyên môn', 5, 'tim-mach', 'vi', 'GENERAL',
  '/media/articles/tam-soat-tieu-duong.jpg'),
 (gen_random_uuid(), 'Tầm soát và phòng ngừa đái tháo đường type 2',
  'tam-soat-va-phong-ngua-tieu-duong-type-2',
  'Đái tháo đường type 2 có thể phòng ngừa được bằng phát hiện sớm tiền đái tháo đường, chế độ ăn và vận động hợp lý.',
  'Đái tháo đường type 2 chiếm hơn 90% các trường hợp đái tháo đường, tiến triển âm thầm qua giai đoạn tiền đái tháo đường (đường huyết đói 5,6-6,9 mmol/L hoặc HbA1c 5,7-6,4%). Tầm soát bằng đường huyết đói hoặc HbA1c ở người có yếu tố nguy cơ: béo phì, ít vận động, tiền sử gia đình, tăng huyết áp. Can thiệp lối sống giảm 5-7% cân nặng kết hợp vận động 150 phút/tuần làm giảm 58% nguy cơ tiến triển thành đái tháo đường. Theo dõi định kỳ HbA1c mỗi 3-6 tháng khi đã điều trị.',
  now() - interval '120 days', true, 'Nội tiết', 'Đội ngũ chuyên môn', 5, 'noi-tiet', 'vi', 'GENERAL',
  '/media/articles/tam-soat-tieu-duong.jpg'),
 (gen_random_uuid(), 'Test hơi thở C13: chẩn đoán vi khuẩn Helicobacter pylori không xâm lấn',
  'test-hoi-tho-c13-chan-doan-vi-khuan-helicobacter-pylori-khong-xam-lan',
  'Test hơi thở C13 là phương pháp không xâm lấn chuẩn để phát hiện vi khuẩn HP, độ chính xác cao, thực hiện nhanh sau nhịn ăn.',
  'Test hơi thở C13 (Urea Breath Test) là phương pháp không xâm lấn chuẩn để chẩn đoán nhiễm vi khuẩn Helicobacter pylori — nguyên nhân hàng đầu của viêm loét dạ dày và ung thư dạ dày. Người bệnh nhịn ăn 4-6 giờ, ngừng thuốc kháng sinh 4 tuần và thuốc ức chế bơm proton 2 tuần trước xét nghiệm để tránh kết quả âm tính giả. Sau khi uống viên nhựa đường C13 và thở vào ống thu mẫu trong khoảng 20 phút, kết quả có độ nhạy và độ đặc hiệu trên 95%. Test dương tính sẽ được điều trị diệt HP theo phác đồ kết hợp.',
  now() - interval '110 days', true, 'Tiêu hóa', 'Đội ngũ chuyên môn', 5, 'tieu-hoa', 'vi', 'GENERAL',
  '/media/articles/viem-loet-da-day.jpg')
ON CONFLICT (slug) DO NOTHING;
